module TopModule (
    input  logic        clk,
    input  logic [7:0]  in,
    output logic [7:0]  anyedge
);

    // Register to store the previous value of the input
    logic [7:0] prev_in;

    // Always block on the positive edge of the clock
    always_ff @(posedge clk) begin
        // Detect any edge (0->1 or 1->0) by XORing current input with previous input
        // The output is set to 1 in the cycle AFTER the transition occurs.
        // By registering the result, we ensure the pulse appears one cycle later.
        anyedge <= in ^ prev_in;

        // Update the previous input register for the next clock cycle
        prev_in <= in;
    end

endmodule

