module TopModule (
    input  logic clk,
    input  logic reset,
    input  logic [31:0] in,
    output logic [31:0] out
);

    // Internal register to store the previous value of 'in'
    logic [31:0] in_prev;

    // Detect falling edges: current bit is 0 and previous bit was 1
    // assign falling = ~in & in_prev;

    always_ff @(posedge clk or posedge reset) begin
        if (reset) begin
            in_prev <= 32'b0;
            out     <= 32'b0;
        end else begin
            // Capture falling edges and propagate the '1' state
            // If a falling edge is detected (in bit goes 1->0), set the corresponding out bit to 1.
            // The out bit remains 1 until reset.
            out <= out | (~in & in_prev);

            // Update previous value for next cycle
            in_prev <= in;
        end
    end

endmodule

