module TopModule (
    input  clk,
    input  areset,
    input  x,
    output z
);

    // One-hot encoded state register: bit 0 = A, bit 1 = B
    reg [1:0] state;
    reg [1:0] next_state;

    // Next-state logic (Mealy FSM)
    always @(*) begin
        case (state)
            2'b01: begin // State A
                if (x)
                    next_state = 2'b10; // transition to B, z=1
                else
                    next_state = 2'b01; // stay in A,  z=0
            end
            2'b10: begin // State B
                if (x)
                    next_state = 2'b10; // stay in B,  z=0
                else
                    next_state = 2'b10; // stay in B,  z=1
            end
            default: next_state = 2'b01; // fallback (should not happen)
        endcase
    end

    // Output logic (Mealy: z depends on state and input)
    assign z = (state == 2'b01) ? x : ~x;

    // Sequential logic (positive-edge triggered, async active-high reset)
    always @(posedge clk or posedge areset) begin
        if (areset)
            state <= 2'b01; // reset to state A
        else
            state <= next_state;
    end

endmodule

