    input  clk,
    input  reset,
    output shift_ena
);

    // Internal state register
    reg [1:0] state;

    // Synchronous reset, active high
    always @(posedge clk) begin
        if (reset) begin
            state <= 2'b00;
        end else begin
            // Detect the proper bit pattern (assumed to be 2'b11 for this implementation)
            // and stay in the enable state for exactly 4 cycles.
            if (state < 2'b11) begin
                state <= state + 1'b1;
            end else begin
                // After 4 cycles, hold the final state (prevents further counting)
                state <= 2'b11;
            end
        end
    end

    // Generate shift_ena pulse for exactly 4 clock cycles
    assign shift_ena = (state != 2'b00);

