module TopModule (
    input  logic clk,
    input  logic areset,
    input  logic in,
    output logic out
);

    // State encoding: 2'b00 = B, 2'b01 = A
    typedef enum logic [1:0] {
        STATE_B = 2'b00,
        STATE_A = 2'b01
    } state_type;

    state_type state, next_state;

    // Next-state logic (Moore machine output depends only on state)
    always_comb begin
        case (state)
            STATE_B: begin
                if (in)
                    next_state = STATE_B;  // B --1--> B
                else
                    next_state = STATE_A;  // B --0--> A
            end
            STATE_A: begin
                if (in)
                    next_state = STATE_A;  // A --1--> A
                else
                    next_state = STATE_B;  // A --0--> B
            end
            default: next_state = STATE_B;
        endcase
    end

    // Output logic (Moore: output is high when in state A)
    assign out = (state == STATE_A) ? 1'b1 : 1'b0;

    // State register with asynchronous active-high reset
