    // Synthesizable implementation of the Karnaugh map function
    // K-map:
    //       x[0]x[1]
    // x[2]x[3] 00 01 11 10
    // 00      | 1 0 0 1 |
    // 01      | 0 0 0 0 |
    // 11      | 1 1 1 0 |
    // 10      | 1 1 0 1 |

    always_comb begin
        // Group 1: x[3]' & x[2]' & (x[0] == x[1])  -> minterms 0, 3
        // Group 2: x[3] & x[2] & (x[0] | x[1])    -> minterms 12, 13, 14
        // Group 3: x[3] & x[2]' & x[1]            -> minterm 6
        // Group 4: x[3] & x[2]' & x[0]'           -> minterm 4

        assign f = (~x[3] & ~x[2] & (x[0] == x[1])) |
                   (x[3] & x[2] & (x[0] | x[1])) |
                   (x[3] & ~x[2] & x[1]) |
                   (x[3] & ~x[2] & ~x[0]);
    end

