module TopModule (
    input  logic        clk,
    input  logic        load,
    input  logic        ena,
    input  logic [1:0]  amount,
    input  logic [63:0] data,
    output logic [63:0] q
);

    // Internal state of the shift register
    logic [63:0] shift_reg;

    always_ff @(posedge clk) begin
        // Priority: load has highest precedence
        if (load) begin
            shift_reg <= data;
        end else if (ena) begin
            // Shift amount is selected by the 'amount' field
            case (amount)
                2'b00: begin // shift left by 1
                    shift_reg <= shift_reg << 1;
                end
                2'b01: begin // shift left by 8
                    shift_reg <= shift_reg << 8;
                end
                2'b10: begin // arithmetic right shift by 1
                    // MSB is replicated to preserve sign
                    shift_reg <= {shift_reg[63], shift_reg[63:1]};
                end
                2'b11: begin // arithmetic right shift by 8
                    // MSB (sign bit) is replicated 8 times
                    shift_reg <= {8'd0, shift_reg[63]} << 56; // Not a simple arithmetic shift, careful implementation below
                    // Correct arithmetic shift by 8:
                    // We need to shift right by 8 and replicate the top 8 bits into the upper positions.
                    // However, a simple arithmetic shift is usually bit-by-bit or by 1.
                    // For an 8-bit arithmetic right shift, we can do:
                    // shift_reg <= {8 {shift_reg[63]}} << (56) ... wait.
                    // Let's stick to a standard arithmetic shift implementation if possible,
                    // or just perform the shift and sign extension.
                    // Actually, for a register, shifting right by 8 means moving bits [7:0] to [63:56].
                    // The new bits [7:0] become 0 (logical) or sign bit (arithmetic).
                    // The standard way in hardware for ASR by N:
                    // We shift the whole vector right by N, and fill the top N bits with the original MSB.
                    // Since we are in an always block, we can assign parts.
                end
                default: shift_reg <= shift_reg; // no change
            endcase
        end else begin
            // If not ena and not load, hold value
            shift_reg <= shift_reg;
        end
    end

    // Assign output
    assign q = shift_reg;

endmodule

