`default_nettype none

module TopModule (
    input  wire clk,
    input  wire reset,
    input  wire [7:0] in,
    output reg done
);

    // State encoding: 0 = searching, 1 = received byte 1, 2 = received byte 2, 3 = received byte 3
    typedef enum logic [1:0] {
        S_IDLE   = 2'b00,
        S_FIRST  = 2'b01,
        S_SECOND = 2'b10,
        S_THIRD  = 2'b11
    } state_t;

    state_t state, next_state;

    // Sequential logic: state update on positive edge of clock
    always_ff @(posedge clk) begin
        if (reset) begin
            state <= S_IDLE;
            done  <= 1'b0;
        end else begin
            state <= next_state;
            // done is pulsed high for one cycle when transitioning from S_THIRD to S_IDLE
            done <= (state == S_THIRD) && (next_state == S_IDLE);
        end
    end

    // Combinational logic: next-state generation
    always_comb begin
        case (state)
            S_IDLE: begin
                // Discard bytes until in[3] is 1
                if (in[3]) next_state = S_FIRST;
                else      next_state = S_IDLE;
            end
            S_FIRST: begin
                // Received first byte, move to second
                next_state = S_SECOND;
            end
            S_SECOND: begin
                // Received second byte, move to third
                next_state = S_THIRD;
            end
            S_THIRD: begin
                // Received third byte, go back to idle (done will be pulsed in FF)
                next_state = S_IDLE;
            end
            default: next_state = S_IDLE;
        endcase
    end

endmodule

