module TopModule (
    input  [5:0] y,   // one-hot state vector
    input        w,
    output       Y1,  // next state bit for flip-flop y[1]
    output       Y3   // next state bit for flip-flop y[3]
);

    // State encoding (one-hot, active high):
    // y[5] = F, y[4] = E, y[3] = D, y[2] = C, y[1] = B, y[0] = A

    // Next-state logic derived by inspection of the FSM transitions:
    //   A(000001) --1--> B(000010) | A(000001) --0--> A
    //   B(000010) --1--> C(000100) | B(000010) --0--> D(001000)
    //   C(000100) --1--> E(010000) | C(000100) --0--> D(001000)
    //   D(001000) --1--> F(100000) | D(001000) --0--> A(000001)
    //   E(010000) --1--> E         | E(010000) --0--> D
    //   F(100000) --1--> C         | F(100000) --0--> D

    // Y1 is the next state for flip-flop y[1] (bit 1, representing state B)
    // From the table:
    //   A->B when w=1 (y[0] & w)   -> sets y[1] to 1
    //   B->C when w=1 (y[1] & w)   -> sets y[1] to 1
    //   C->E when w=1 (y[2] & w)   -> sets y[1] to 0
    //   D->F when w=1 (y[3] & w)   -> sets y[1] to 0
    //   E->E when w=1              -> sets y[1] to 0
    //   F->C when w=1              -> sets y[1] to 0
    //   All other transitions (w=0) keep y[1] = 0 (reset) except A->A and B->D
    //   which leave y[1] = 0.
    // The only transitions that set y[1] = 1 are A->B and B->C.
    assign Y1 = y[0] & w | y[1] & w;

    // Y3 is the next state for flip-flop y[3] (bit 3, representing state D)
    // From the table:
    //   A->A when w=0 (y[0] & ~w)  -> sets y[3] to 0 (stays 0)
    //   A->B when w=1              -> sets y[3] to 0
    //   B->C when w=1              -> sets y[3] to 0
    //   B->D when w=0 (y[1] & ~w)  -> sets y[3] to 1
    //   C->E when w=1              -> sets y[3] to 0
    //   C->D when w=0 (y[2] & ~w)  -> sets y[3] to 1
    //   D->F when w=1              -> sets y[3] to 0
    //   D->A when w=0              -> sets y[3] to 0
    //   E->E when w=1              -> sets y[3] to 0
    //   E->D when w=0              -> sets y[3] to 1
    //   F->C when w=1              -> sets y[3] to 0
    //   F->D when w=0              -> sets y[3] to 1
    //   All remaining transitions keep y[3] = 0.
    // The transitions that set y[3] = 1 are: B->D, C->D, E->D, F->D.
    // In one-hot, these correspond to (state & ~w):
    assign Y3 = (y[1] & ~w) | (y[2] & ~w) | (y[4] & ~w) | (y[5] & ~w);

endmodule

