module TopModule (
    input  logic clk,
    input  logic reset,
    input  logic s,
    input  logic w,
    output logic z
);

    // State encoding (2 bits minimal for states A and B)
    typedef enum logic [1:0] {
        A = 2'b00,
        B = 2'b01
    } state_t;

    state_t state, next_state;

    // Register for the 3-cycle w counter (how many of the last 3 cycles w was 1)
    logic [1:0] cnt;

    // Combinational next-state logic
    always_comb begin
        next_state = state;   // default: stay in current state
        z          = 1'b0;    // default: z low

        case (state)
            A: begin
                if (s == 1'b1)
                    next_state = B;
                // else stay in A, z stays 0
            end

            B: begin
                // Count how many of the last 3 cycles w was 1
                // cnt is updated on every positive edge while in B
                // We compute the new count for the next cycle here
                // (the actual register update happens in the always_ff block)

                // Check the condition: exactly two of the last three w's were 1
                // The current cnt value (from previous cycles) plus the new w
                // gives the count for the sliding window of the last 3 cycles
                if (cnt + w == 2'b11) begin // cnt + w == 2 means exactly two 1's
                    z = 1'b1;
                end else begin
                    z = 1'b0;
                end
                // Remain in state B; FSM continues checking w
            end
        endcase
    end

    // Sequential always block: clocked logic
    always_ff @(posedge clk) begin
        if (reset) begin
            state   <= A;
            cnt     <= 2'b00;
        end else begin
            state <= next_state;

            // Update the 3-cycle counter
            // Shift register style: new bit is w, LSB is discarded
            // cnt[1] gets previous cnt[0], cnt[0] gets new w
            cnt <= { cnt[0], w };
        end
    end

endmodule

