module TopModule (
    input  logic clk,
    input  logic load,
    input  logic [511:0] data,
    output logic [511:0] q
);

    // Internal storage for the current cell state
    logic [511:0] q_int;

    // Generate the next state combinatorially
    // q[i] next = f(q[i-1], q[i], q[i+1]) according to Rule 110
    always_comb begin
        // Handle boundaries: q[-1] = 0, q[512] = 0
        // For i = 0:  left = 0, center = q_int[0], right = q_int[1]
        // For i = 511: left = q_int[510], center = q_int[511], right = 0
        for (int i = 0; i < 512; i++) begin
            logic left, center, right;
            logic [7:0] rule_index;

            if (i == 0) begin
                left   = 1'b0;
                center = q_int[0];
                right  = q_int[1];
            end else if (i == 511) begin
                left   = q_int[510];
                center = q_int[511];
                right  = 1'b0;
            end else begin
                left   = q_int[i-1];
                center = q_int[i];
                right  = q_int[i+1];
            end

            // Rule 110 lookup table
            // Index formed as (left << 2) | (center << 1) | right
            rule_index = {left, center, right};

            case (rule_index)
                3'b111: q_int[i] = 1'b0; // 7 -> 0
                3'b110: q_int[i] = 1'b1; // 6 -> 1
                3'b101: q_int[i] = 1'b1; // 5 -> 1
                3'b100: q_int[i] = 1'b0; // 4 -> 0
                3'b011: q_int[i] = 1'b1; // 3 -> 1
                3'b010: q_int[i] = 1'b1; // 2 -> 1
                3'b001: q_int[i] = 1'b1; // 1 -> 1
                3'b000: q_int[i] = 1'b0; // 0 -> 0
                default: q_int[i] = 1'b0;
            endcase
        end
    end

    // Sequential logic: update on positive clock edge
    always_ff @(posedge clk) begin
        if (load) begin
            q_int <= data;
        end else begin
            q_int <= q_int; // hold state (optional, for clarity)
        end
    end

    // Continuous assignment to output
    assign q = q_int;

endmodule

