module TopModule (
    input  in,
    input  [3:0] state,
    output [3:0] next_state,
    output out
);

    // Decode current state to enable bit
    wire sA = state[0]; // A = 4'b0001
    wire sB = state[1]; // B = 4'b0010
    wire sC = state[2]; // C = 4'b0100
    wire sD = state[3]; // D = 4'b1000

    // Next state logic (combinational)
    // State A (sA): next = in ? B : A  ->  sB_next = in & ~sA;  sA_next = ~in & sA;
    // State B (sB): next = in ? B : C  ->  sB_next = ~in & sB | in;   sC_next = ~in & sB;
    // State C (sC): next = in ? D : A  ->  sD_next = ~in & sC;    sA_next = ~in & sC;
    // State D (sD): next = in ? B : C  ->  sB_next = ~in & sD;    sC_next = ~in & sD;

    // Build next_state bits directly from inspection of the truth table
    // Using the derived equations for one-hot transition:
    // A->in=0:A, in=1:B   => sA_next = ~in & sA;  sB_next += in & ~sA;
    // B->in=0:C, in=1:B   => sC_next = ~in & sB;  sB_next += in & sB;
    // C->in=0:A, in=1:D   => sA_next = ~in & sC;  sD_next = in & sC;
    // D->in=0:C, in=1:B   => sC_next = ~in & sD;  sB_next += in & sD;

    // We can express the next state bits as muxes based on current state and in
    // Since only one state bit is high at a time, we decode the transition.

    // next_state[0] = A_next
    assign next_state[0] = (~in & sA) | (~in & sC); // from A and C both go to A when in=0
    // Actually from table: A->A, C->A when in=0. B->C, D->C when in=0.
    // Let's re-derive cleanly:
    // A(in=0)->A, (in=1)->B  => A_next = ~in & sA
    // B(in=0)->C, (in=1)->B  => B_next = in | ~in & sB  (but in one-hot we just set the target)
    // C(in=0)->A, (in=1)->D  => C_next = ~in & sC
    // D(in=0)->C, (in=1)->B  => D_next = ~in & sD

    // Correct next_state equations for one-hot:
    // The next state bit is 1 if the current state is the source and the transition targets that bit.
    // We can write:
    assign next_state[0] = (~in & sA) | (~in & sC); // A->A, C->A
    assign next_state[1] = (in & sA) | (~in & sB) | (in & sD); // A->B, B->B, D->B
    assign next_state[2] = (in & sB) | (~in & sC) | (~in & sD); // B->C, C->D? wait C->D when in=1, so C->D sets bit 3. C->A when in=0 sets bit 0. So bit 2 (C) is target from B(in=0) and D(in=0). Also B(in=1) stays B (bit1). Let's check table:
    // B: in=0 -> C (bit2), in=1 -> B (bit1)
    // C: in=0 -> A (bit0), in=1 -> D (bit3)
    // D: in=0 -> C (bit2), in=1 -> B (bit1)
    // So bit2 (C) next: from B(in=0) and D(in=0). -> (~in & sB) | (~in & sD)
    // Let's correct the equations systematically.

    // Let's list transitions:
    // Current \ Next  A   B   C   D
    // A       in=0  1   0   0   0
    // A       in=1  0   1   0   0
    // B       in=0  0   0   1   0
    // B       in=1  0   1   0   0
    // C       in=0  1   0   0   0
    // C       in=1  0   0   0   1
    // D       in=0  0   1   0   0
    // D       in=1  0   1   0   0

    // Next state bit 0 (A): 1 when (sA & ~in) or (sC & ~in)
    assign next_state[0] = (~in & sA) | (~in & sC);

    // Next state bit 1 (B): 1 when (sA & in) or (sB & in) or (sD & in)
    // From table: A->B(in=1), B->B(in=1), D->B(in=1). Also B->B is stay.
    assign next_state[1] = (in & sA) | (in & sB) | (in & sD);

    // Next state bit 2 (C): 1 when (sB & ~in) or (sD & ~in)
    // From table: B->C(in=0), D->C(in=0)
    assign next_state[2] = (~in & sB) | (~in & sD);

    // Next state bit 3 (D): 1 when (sC & in)
    // From table: C->D(in=1)
    assign next_state[3] = (in & sC);

    // Output logic (Moore machine: output depends only on state)
    // Output is 1 only in state D
    assign out = sD;

endmodule

