`default_nettype none

module TopModule (
    input  wire clk,
    input  wire areset,
    input  wire bump_left,
    input  wire bump_right,
    input  wire ground,
    input  wire dig,
    output wire walk_left,
    output wire walk_right,
    output wire aaah,
    output wire digging
);

    // State encoding: 2 bits
    typedef enum logic [1:0] {
        WALKING_LEFT   = 2'b00,
        WALKING_RIGHT  = 2'b01,
        FALLING        = 2'b10,
        DIGGING        = 2'b11
    } state_t;

    state_t state, next_state;

    // ============ Combinational logic for next state ============
    always_comb begin
        // Default assignments: hold current state unless overridden
        next_state = state;

        // Priority: Fall > Dig > Switch directions
        // 1. Fall has highest precedence
        if (ground == 1'b0) begin
            next_state = FALLING;
        end
        // 2. Dig: only if walking on ground (ground=1 and not falling)
        else if (dig == 1'b1 && state != FALLING) begin
            next_state = DIGGING;
        end
        // 3. Switch directions when bumped (while walking)
        else if (state != FALLING && state != DIGGING) begin
            // Bumped on both sides -> switch direction
            if (bump_left == 1'b1 && bump_right == 1'b1) begin
                if (state == WALKING_LEFT)  next_state = WALKING_RIGHT;
                else                        next_state = WALKING_LEFT;
            end
            // Bumped only on left -> walk right
            else if (bump_left == 1'b1) begin
                next_state = WALKING_RIGHT;
            end
            // Bumped only on right -> walk left
            else if (bump_right == 1'b1) begin
                next_state = WALKING_LEFT;
            end
        end
    end

    // ============ Sequential logic (flip-flops) ============
    always_ff @(posedge clk or posedge areset) begin
        if (areset == 1'b1) begin
            state <= WALKING_LEFT;  // Reset to walk left
        end else begin
            state <= next_state;
        end
    end

    // ============ Output logic (Moore machine) ============
    // Outputs are asserted based on the current state (Moore)
    assign walk_left  = (state == WALKING_LEFT);
    assign walk_right = (state == WALKING_RIGHT);
    assign aaah       = (state == FALLING);
    assign digging    = (state == DIGGING);

endmodule

