    input  logic clk,
    input  logic areset,
    input  logic in,
    output logic out
);

    // State encoding: 2 bits for 4 states (A, B, C, D)
    typedef enum logic [1:0] {
        A = 2'b00,
        B = 2'b01,
        C = 2'b10,
        D = 2'b11
    } state_type;

    state_type state, next_state;

