                next_state = state_type'(in ? 2'b11 : 2'b00);
                out        = 1'b0;
            end
            D: begin
                next_state = state_type'(in ? 2'b01 : 2'b10);
                out        = 1'b1;
            end
            default: begin
                next_state = A;
                out        = 1'b0;
            end
        endcase
    end

    // State register (sequential, positive edge triggered, async reset)
