module TopModule (
    input  clk,
    input  areset,
    input  bump_left,
    input  bump_right,
    output walk_left,
    output walk_right
);

    // Internal state signal for the Moore machine
    reg [1:0] state;

    // Next state logic (combinational)
    always @(*) begin
        case (state)
            2'b00: begin // Currently walking left
                if (bump_left | bump_right)
                    state = 2'b01; // Switch to walking right
                else
                    state = 2'b00; // Stay walking left
            end
            2'b01: begin // Currently walking right
                if (bump_left | bump_right)
                    state = 2'b00; // Switch to walking left
                else
                    state = 2'b01; // Stay walking right
            end
            default: state = 2'b00; // Fallback
        endcase
    end

    // State flip-flops (sequential logic, positive edge triggered)
    always @(posedge clk or posedge areset) begin
        if (areset)
            state <= 2'b00; // Asynchronous reset to walk left
        else
            state <= state; // State is updated based on combinational logic
    end

    // Output logic (Moore machine: outputs depend only on state)
    // walk_left is 1 when state is 00 (walking left)
    // walk_right is 1 when state is 01 (walking right)
    assign walk_left = (state == 2'b00);
    assign walk_right = (state == 2'b01);

endmodule

