module TopModule (
    input  logic clk,
    input  logic load,
    input  logic [255:0] data,
    output logic [255:0] q
);

    // Internal register for the current state (256 bits)
    logic [255:0] state;

    // Helper signals for neighbour counts (256 entries, each 4 bits wide)
    logic [3:0] neighbours [255:0];

    // Instantiate 256 neighbour counters
    genvar i;
    generate
        for (i = 0; i < 256; i = i + 1) begin: counter
            // 4-bit counter to hold neighbour count (max 8)
            always_ff @(posedge clk) begin
                if (load) begin
                    neighbours[i] <= 4'b0;
                end else begin
                    neighbours[i] <= neighbours[i];
                end
            end

            // Combinational neighbour counting
            always_comb begin
                int r, c;
                int nr, nc;
                int count;
                int rr, cc;

                // Map linear index to 2D coordinates (row, col)
                // Row 0 is bits 15:0, Row 1 is bits 31:16, ..., Row 15 is bits 255:240
                r = i / 16;
                c = i % 16;

                count = 0;
                // Iterate over 8 neighbours with toroidal wrapping
                for (nr = -1; nr <= 1; nr = nr + 1) begin
                    for (nc = -1; nc <= 1; nc = nc + 1) begin
                        if (nr == 0 && nc == 0) continue; // skip self

                        // Wrap-around indices
                        rr = (r + nr + 16) % 16;
                        cc = (c + nc + 16) % 16;

                        // Map 2D back to linear index
                        // Row rr starts at bit (rr * 16)
                        // Column cc is bit cc within that row
                        count = count + state[rr * 16 + cc];
                    end
                end

                neighbours[i] = count[3:0]; // store 4-bit count
            end
        end
    endgenerate

    // Compute next_state based on current state and neighbours
    logic [255:0] next_state;
    always_comb begin
        int i;
        for (i = 0; i < 256; i = i + 1) begin
            case (neighbours[i])
                4'd0, 4'd1: next_state[i] = 1'b0;           // Rule (1): 0-1 neighbour -> 0
                4'd2:     next_state[i] = state[i];         // Rule (2): 2 neighbours -> stay same
                4'd3:     next_state[i] = 1'b1;             // Rule (3): 3 neighbours -> 1
                default:  next_state[i] = 1'b0;             // Rule (4): 4+ neighbours -> 0
            endcase
        end
    end

    // Update state register: load synchronous, otherwise update every clock
    always_ff @(posedge clk) begin
        if (load) begin
            state <= data;
        end else begin
            state <= next_state;
        end
    end

    // Output assignment: q reflects the current state
    assign q = state;

endmodule

