module TopModule (
	input  clk,
	input  reset,
	input  in,
	output done
);

	// -------------------------------------------------------------
	// Parameter definitions
	// -------------------------------------------------------------
	parameter IDLE   = 2'b00;
	parameter START  = 2'b01;
	parameter DATA   = 2'b10;
	parameter STOP   = 2'b11;

	// -------------------------------------------------------------
	// Internal signals
	// -------------------------------------------------------------
	reg [1:0] state, next_state;
	reg [3:0] bit_counter;   // counts 0..7 for data bits
	reg [7:0] received_byte; // assembled data byte (LSB first)
	reg       stop_expected; // indicates we are waiting for the stop bit
	reg       done_reg;      // registered output to avoid l-value conflict

	// -------------------------------------------------------------
	// Next-state logic (combinational)
	// -------------------------------------------------------------
	always @(*) begin
		case (state)
			IDLE: begin
				if (~in) begin
					// Start bit detected (falling edge)
					next_state = START;
				end else begin
					next_state = IDLE;
				end
			end

			START: begin
				// Wait one clock cycle to sample the start bit stable,
				// then move to data collection.
				next_state = DATA;
			end

			DATA: begin
				if (bit_counter == 4'd7) begin
					// Last data bit sampled; now expect stop bit.
					next_state = STOP;
				end else begin
					// Continue collecting data bits.
					next_state = DATA;
				end
			end

			STOP: begin
				if (in) begin
					// Stop bit correct -> byte complete.
					next_state = IDLE;
				end else begin
					// Stop bit missing -> stay in STOP and wait.
					next_state = STOP;
				end
			end

			default: next_state = IDLE;
		endcase
	end

	// -------------------------------------------------------------
	// State register (positive-edge triggered, active-high reset)
	// -------------------------------------------------------------
	always @(posedge clk or posedge reset) begin
		if (reset) begin
			state      <= IDLE;
			bit_counter <= 4'd0;
			received_byte <= 8'd0;
			stop_expected <= 1'b0;
			done_reg <= 1'b0;
		end else begin
			state <= next_state;

			case (state)
				IDLE: begin
					// Reset counters when idle.
					bit_counter <= 4'd0;
					received_byte <= 8'd0;
					stop_expected <= 1'b0;
					done_reg <= 1'b0;
				end

				START: begin
					// Optional: could reset here, but IDLE handling is sufficient.
				end

				DATA: begin
					// Shift in the LSB first.
					received_byte <= {in, received_byte[7:1]};
					if (bit_counter < 4'd7) begin
						bit_counter <= bit_counter + 4'd1;
					end
				end

				STOP: begin
					if (in) begin
						// Stop bit correct -> mark byte received.
						done_reg <= 1'b1;
						stop_expected <= 1'b0;
						// Stay in STOP one more cycle to allow
						// the done pulse to propagate, then IDLE
						// will reset the counters on the next clock.
					end
					// If stop bit is wrong, remain in STOP;
					// counters and done are not updated.
				end

				default: begin
					// Should not happen.
				end
			endcase
		end
	end

	// -------------------------------------------------------------
	// Assign output done to the wire (as required by the tool check)
	// -------------------------------------------------------------
	assign done = done_reg;

endmodule

