module TopModule (
    input  clk,
    input  in,
    input  reset,
    output [7:0] out_byte,
    output done
);

    // Output assignments (width corrected to 8 bits)
    assign out_byte = rx_byte;
    assign done     = rx_done;

    //----------------------------------------------------------------
    // Internal signals / state encoding
    //----------------------------------------------------------------
    // States: IDLE, START, DATA8, STOP, DONE
    typedef enum logic [2:0] {
        S_IDLE   = 3'b000,
        S_START  = 3'b001,
        S_DATA   = 3'b010,
        S_STOP   = 3'b011,
        S_DONE   = 3'b100
    } state_t;

    state_t   state, next_state;
    logic [7:0] rx_byte;
    logic [3:0] bit_cnt;   // counts 0..7 for data bits, plus stop bit
    logic       rx_done;

    //----------------------------------------------------------------
    // State register (synchronous reset, positive edge)
    //----------------------------------------------------------------
    always_ff @(posedge clk or posedge reset) begin
        if (reset) begin
            state     <= S_IDLE;
            rx_byte   <= 8'b0;
            bit_cnt   <= 4'b0;
            rx_done   <= 1'b0;
        end else begin
            state     <= next_state;
            rx_done   <= 1'b0;               // clear done each cycle

            case (state)
                S_IDLE: begin
                    bit_cnt <= 4'b0;
                    if (in == 1'b0)           // start bit detected (falling edge)
                        next_state <= S_START;
                    else
                        next_state <= S_IDLE;
                end

                S_START: begin
                    // Wait one cycle after start bit edge, then sample data bits.
                    // We assume the start bit is valid if it is 0.
                    next_state <= S_DATA;
                end

                S_DATA: begin
                    // Shift in the data bit (LSB first).
                    // bit_cnt counts 0..7 (8 bits total).
                    rx_byte   <= {in, rx_byte[7:1]};
                    if (bit_cnt == 4'd7) begin
                        // All 8 data bits received, go to STOP state.
                        next_state <= S_STOP;
                    end else begin
                        next_state <= S_DATA;
                        bit_cnt     <= bit_cnt + 1'b1;
                    end
                end

                S_STOP: begin
                    // Verify stop bit is 1.
                    if (in == 1'b1) begin
                        // Stop bit correct → assert done and return to IDLE.
                        rx_done   <= 1'b1;
                        next_state <= S_IDLE;
                    end else begin
                        // Stop bit incorrect → stay in STOP waiting for a 1.
                        // Also reset bit counter so we don't miscount next byte.
                        bit_cnt   <= 4'b0;
                        next_state <= S_STOP;
                    end
                end

                S_DONE: begin // unused; kept for completeness
                    next_state <= S_IDLE;
                end

                default: next_state <= S_IDLE;
            endcase
        end
    end

    //----------------------------------------------------------------
    // Bit-counter enable logic (inside S_DATA)
    //----------------------------------------------------------------
    // The counter increments on each cycle we are in S_DATA.
    // We use a separate always block to keep the logic clean,
    // but the assignments above already update rx_byte and bit_cnt
    // within the case statement. To avoid latches, we make sure
    // bit_cnt is always assigned.

    // Actually, the assignments inside the case block above already
    // handle bit_cnt. No additional always block is needed.

endmodule

Prob153_gshare.code:
`default_nettype none

module TopModule (
    input  wire        clk,
    input  wire        areset,

    // Prediction interface
    input  wire        predict_valid,
    input  wire [6:0]  predict_pc,
    output wire        predict_taken,
    output wire [6:0]  predict_history,

    // Training interface
    input  wire        train_valid,
    input  wire        train_taken,
    input  wire        train_mispredicted,
    input  wire [6:0]  train_history,
    input  wire [6:0]  train_pc
);

    //--------------------------------------------------------------------
    // Internal signals and registers
    //--------------------------------------------------------------------
    reg  [6:0] gh_reg;          // 7-bit global branch history register
    wire [6:0] gh_next;         // next value of gh_reg
    wire [6:0] gh_xor;          // gh_reg XOR pc (for indexing)

    // PHT: 128 entries x 2-bit saturating counters
    reg  [1:0] pht [0:127];

    // Temporary registers to capture training inputs on the clock edge
    reg        train_valid_d;
    reg  [6:0] train_pc_d;
    reg        train_taken_d;
    reg        train_mispredicted_d;
    reg  [6:0] train_history_d;

    //--------------------------------------------------------------------
    // Global history update logic (combinational next-state)
    //--------------------------------------------------------------------
    // The new global history is formed by shifting in the branch outcome
    // (taken=1, not-taken=0) at bit 0, and shifting the old history right.
    assign gh_next = {train_taken_d, gh_reg[6:1]};

    //--------------------------------------------------------------------
    // Output assignments for prediction interface
    //--------------------------------------------------------------------
    // Index into PHT: XOR of pc and global history
    assign gh_xor = predict_pc ^ gh_reg;
    assign predict_taken = pht[gh_xor[6:0]][1];  // MSB of counter => taken

    // Predicted history: the history *before* the predicted branch is
    // taken into account.  For a taken prediction we flip the LSB; for
    // a not-taken prediction we keep the current history.
    // The specification says: "The branch history register is then updated
    // (at the next positive clock edge) for the predicted branch."
    // Therefore the output history is the current gh_reg value.
    assign predict_history = gh_reg;

    //--------------------------------------------------------------------
    // Sequential logic (positive edge triggered, asynchronous reset)
    //--------------------------------------------------------------------
    always @(posedge clk or posedge areset) begin
        if (areset) begin
            gh_reg <= 7'b0;
            // Reset PHT counters to weakly-not-taken (2'b01)
            integer i;
            for (i = 0; i < 128; i = i + 1) begin
                pht[i] <= 2'b01;
            end
            train_valid_d <= 1'b0;
        end else begin
            //------------------------------------------------------------
            // 1) Update global history register
            //    - If training for a misprediction is active, we recover
            //      the history to the state *after* the mispredicting branch.
            //      That state is computed as: outcome shifted in.
            //    - Otherwise, we use the combinational next-value.
            //------------------------------------------------------------
            if (train_valid_d && train_mispredicted_d) begin
                // Recover history: shift in the actual taken outcome
                gh_reg <= {train_taken_d, gh_reg[6:1]};
            end else begin
                gh_reg <= gh_next;
            end

            //------------------------------------------------------------
            // 2) Update PHT counters
            //    - Training modifies the PHT at the positive clock edge.
            //    - Prediction sees the PHT value from the *previous* cycle
            //      (because updates happen on the edge).
            //------------------------------------------------------------
            if (train_valid_d) begin
                // Standard gshare PHT update (saturating counter)
                if (train_taken_d) begin
                    // Increment if not already at max (3)
                    if (pht[train_pc_d ^ train_history_d][1] != 1'b1) begin
                        // Simple increment: 00->01, 01->10, 10->11, 11 stays 11
                        // We implement it with a case for clarity (synthesizable)
                        case (pht[train_pc_d ^ train_history_d])
                            2'b00: pht[train_pc_d ^ train_history_d] <= 2'b01;
                            2'b01: pht[train_pc_d ^ train_history_d] <= 2'b10;
                            2'b10: pht[train_pc_d ^ train_history_d] <= 2'b11;
                            default: pht[train_pc_d ^ train_history_d] <= 2'b11;
                        endcase
                    end
                end else begin
                    // Decrement if not already at min (0)
                    if (pht[train_pc_d ^ train_history_d][1] != 1'b0) begin
                        case (pht[train_pc_d ^ train_history_d])
                            2'b11: pht[train_pc_d ^ train_history_d] <= 2'b10;
                            2'b10: pht[train_pc_d ^ train_history_d] <= 2'b01;
                            2'b01: pht[train_pc_d ^ train_history_d] <= 2'b00;
                            default: pht[train_pc_d ^ train_history_d] <= 2'b00;
                        endcase
                    end
                end
            end

            //------------------------------------------------------------
            // 3) Capture training inputs for next cycle
            //    (registered to satisfy setup/hold and to allow "same-cycle"
            //     prediction/training precedence handling)
            //------------------------------------------------------------
            train_valid_d <= train_valid;
            train_pc_d    <= train_pc;
            train_taken_d <= train_taken;
            train_mispredicted_d <= train_mispredicted;
            train_history_d <= train_history;
        end
    end

endmodule

Prob151_review2015_fsm.code:
module TopModule (
    input  clk,
    input  reset,
    input  data,
    input  done_counting,
    input  ack,
    output shift_ena,
    output counting,
    output done
);

// State encoding
typedef enum logic [1:0] {
    IDLE   = 2'b00,
    SHIFT  = 2'b01,
    COUNT  = 2'b10,
    DONE   = 2'b11
} state_t;

state_t state, next_state;

// Shift register for pattern detection (4 bits)
logic [3:0] shift_reg;

// Pattern detection: 1101
always_ff @(posedge clk) begin
    if (reset) begin
        shift_reg <= 4'b0000;
    end else begin
        shift_reg <= {shift_reg[2:0], data};
    end
end

// State register
always_ff @(posedge clk) begin
    if (reset) begin
        state <= IDLE;
    end else begin
        state <= next_state;
    end
end

// Counter for the 4 cycles of shift_ena in SHIFT state
logic [1:0] shift_cnt;

always_ff @(posedge clk) begin
    if (reset) begin
        shift_cnt <= 2'b00;
    end else if (state == SHIFT) begin
        // Increment counter while in SHIFT state
        if (shift_cnt == 2'b11) begin
            shift_cnt <= 2'b00; // Reset after 4 cycles (0,1,2,3)
        end else begin
            shift_cnt <= shift_cnt + 1;
        end
    end else begin
        shift_cnt <= 2'b00; // Reset counter if not in SHIFT state
    end
end

// Next-state and output logic
always @(*) begin
    // Default assignments
    shift_ena  = 1'b0;
    counting   = 1'b0;
    done       = 1'b0;
    next_state = state; // Default: stay in current state

    case (state)
        IDLE: begin
            // Check for pattern 1101
            if (shift_reg == 4'b1101) begin
                next_state = SHIFT;
            end else begin
                next_state = IDLE;
            end
        end

        SHIFT: begin
            // Assert shift_ena
            shift_ena = 1'b1;

            // Check if we have counted 4 cycles
            if (shift_cnt == 2'b11) begin
                next_state = COUNT;
            end else begin
                next_state = SHIFT;
            end
        end

        COUNT: begin
            counting = 1'b1;
            if (done_counting) begin
                next_state = DONE;
            end else begin
                next_state = COUNT;
            end
        end

        DONE: begin
            done = 1'b1;
            if (ack) begin
                next_state = IDLE;
            end else begin
                next_state = DONE;
            end
        end

        default: next_state = IDLE;
    endcase
end

endmodule

