module TopModule (
    input  logic clk,
    input  logic load,
    input  logic [511:0] data,
    output logic [511:0] q
);

    // Internal register to hold the current state
    logic [511:0] state;

    always_ff @(posedge clk) begin
        if (load) begin
            // Load the parallel data input into the state register
            state <= data;
        end else begin
            // Compute Rule 90 next state for all 512 bits using a generate block
            // Boundary cells q[-1] and q[512] are assumed to be 0.
            genvar i;
            generate
                for (i = 0; i < 512; i = i + 1) begin: cell
                    // Determine left neighbour: state[i-1] if i > 0, else 0
                    // Determine right neighbour: state[i+1] if i < 511, else 0
                    // The next state is the XOR of the left and right neighbours.

                    // We use continuous assignment expressions inside the 
                    // non-blocking assignment to handle boundary conditions.

                    // Left neighbor: 0 if i is 0, else state[i-1]
                    // Right neighbor: 0 if i is 511, else state[i+1]

                    // Assignment: Next state bit <= Left XOR Right
                    // Note: Reading state[i-1] or state[i+1] here reads the 
                    // current (old) value of the register, which is correct 
                    // for calculating the next state on the positive edge.

                    // Using ternary operators for boundary conditions
                    logic left_neigh, right_neigh;

                    // Assign neighbors signals
                    // Note: In some strict Verilog versions, reading state[i-1] 
                    // inside a generate block requires i>0 check to avoid 
                    // indexing 0-1, but the ternary handles it.
                    assign left_neigh = (i == 0) ? 1'b0 : state[i-1];
                    assign right_neigh = (i == 511) ? 1'b0 : state[i+1];

                    // Update the state register bit
                    // The RHS computes the XOR of neighbors.
                    // The LHS targets the specific bit in the state register.
                    state[i] <= left_neigh ^ right_neigh;
                end
            endgenerate
        end
    end

    // Assign the output q to the current state.
    // This ensures q reflects the CA state.
    // If load was high, state was updated to data, so q will follow.
    assign q = state;

endmodule
